                        quote: "مَرَرْتُ لَيْلَةَ أَمْسِ بِرَجُلٍ بَائِسٍ يَشْكُو أَلَمَ الجُوعِ فَفَثَأْتُهُ عَنْهُ، ثُمَّ زُرْتُ صَدِيقًا مِنْ أَرْبَابِ الثَّرَاءِ فَوَجَدْتُهُ يَشْكُو أَلَمَ البِطْنَةِ! فَقُلْتُ: يَا لَلْعَجَبِ! لَوْ أَعْطَى الغَنِيُّ الفَقِيرَ مَا فَضَلَ عَنْ حَاجَتِهِ مَا شَكَا وَاحِدٌ مِنْهُمَا سَقَمًا؛ لَكِنَّهُ ضَمَّ إِلَى مَائِدَتِهِ مَا اخْتَلَسَهُ مِنْ صَحْفَةِ الفَقِيرِ، فَعَاقَبَهُ اللهُ بِالبِطْنَةِ، وَهَكَذَا يَصْدُقُ المَثَلُ: بِطْنَةُ الغَنِيِّ انْتِقَامٌ لِجُوعِ الفَقِيرِ. مَا ضَنَّتِ السَّمَاءُ بِمَائِهَا، وَلَا شَحَّتِ الأَرْضُ بِنَبَاتِهَا، وَلَكِنَّ القَوِيَّ حَسَدَ الضَّعِيفَ فَزَوَاهُمَا عَنْهُ، فَأَصْبَحَ فَقِيرًا غُرَمَاؤُهُ الأَغْنِيَاءُ لَا الأَرْضُ وَالسَّمَاءُ. لَيْتَنِي أَمْلِكُ عَقْلَهُمْ لأَتَصَوَّرَ حُجَّتَهُمْ فِي أَنَّهُمْ أَقْوِيَاءُ أَوْ وَرِثُوا المَالَ؛ فَإِنْ كَانَتِ القُوَّةُ حُجَّتَهُمْ فَلِمَ لَا يَسْلُبُونَ أَرْوَاحَهُمْ كَمَا سَلَبُوا أَمْوَالَهُمْ؟ وَإِنْ كَانَتِ الأُبُوَّةُ عِلَّةَ المِيرَاثِ فَلِمَ وَرِثْتُمُوهُمْ فِي أَمْوَالِهِمْ وَلَمْ تَرِثُوهُمْ فِي مَظَالِمِهِمْ؟ فَاخْلُفُوهُمْ فِي رَدِّ المَالِ إِلَى أَرْبَابِهِ لَا فِي الاسْتِمْرَارِ عَلَى اغْتِصَابِهِ.",
